/**
 * @suppress
 */
public object FfiConverterTypeStore: FfiConverter<Store, Long> {
    override fun lower(value: Store): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Store {
        return Store(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Store {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Store) = 8UL

    override fun write(value: Store, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



