sealed class AutofillApiException: kotlin.Exception() {
    
    class SqlException(
        
        val `reason`: kotlin.String
        ) : AutofillApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InterruptedException(
        ) : AutofillApiException() {
        override val message
            get() = ""
    }
    
    class CryptoException(
        
        val `reason`: kotlin.String
        ) : AutofillApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NoSuchRecord(
        
        val `guid`: kotlin.String
        ) : AutofillApiException() {
        override val message
            get() = "guid=${ `guid` }"
    }
    
    class UnexpectedAutofillApiException(
        
        val `reason`: kotlin.String
        ) : AutofillApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AutofillApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): AutofillApiException = FfiConverterTypeAutofillApiError.lift(error_buf)
    }

    
}

